# Calculators added 2026-11-11 (wire size, pool volume, BTU, studs, rebar). Same entry shape as tools4.py.
def _u(us,mt): return f"<span class='usc'>{us}</span><span class='mtc'>{mt}</span>"
def _js5(k): return open("pm5/common.js").read()+open(f"pm5/{k}.js").read()
def _uu(html,u): return html.replace("<div class='f","<div data-uu='"+str(u)+"' class='f",1)
_ST5="✓ Formulas and table values checked against the cited sources · Updated November 2026"
_NEC="<span class='nod'>NEC 2023 Table 310.16</span>"
