_SAFE_E="Estimate only. Have a licensed electrician confirm the wire size, breaker and local code before you install."
_OVAL="<svg viewBox='0 0 220 110' width='220' height='110' role='img' aria-hidden='true' style='max-width:100%;height:auto'><ellipse cx='110' cy='55' rx='100' ry='45' fill='#dbeafe' stroke='#1d4ed8' stroke-width='2'/><path d='M10 55H210M110 10V100' stroke='#1d4ed8' stroke-dasharray='4 3'/><text x='150' y='50' font-size='14' fill='#0f172a'>L</text><text x='114' y='30' font-size='14' fill='#0f172a'>W</text></svg>"
